#[cfg(test)]mod prefix_retained_core_tests{
 use super::*;use crate::circuit::{analyze_ops,OperationType as K};use crate::sim::Simulator;use sha3::{Shake256,digest::{Update,ExtendableOutput,XofReader}};
 struct Words{bytes:Vec<u8>,at:usize}impl XofReader for Words{fn read(&mut self,out:&mut[u8]){out.copy_from_slice(&self.bytes[self.at..self.at+out.len()]);self.at+=out.len();}}
 #[test]fn all_retention_frontiers_match_all_inputs_guards_and_every_phase_coefficient(){
  let mut words=include_str!("prefix_schedule_expected.dat").split_whitespace().map(|x|x.parse::<u64>().unwrap());assert_eq!(words.next(),Some(34));assert_eq!(words.next(),Some(256));let expected:Vec<Vec<_>>=(0..14).map(|_|(0..256).map(|_|words.next().unwrap()).collect()).collect();
  for(index,&keep)in RETENTION_MASKS.iter().enumerate(){let draws=42-index;let mut c=Builder::new();let input=c.alloc_qubits(14);let guard=c.alloc_bit();c.push_condition(guard);let(_,peak)=c.r3_peak(|c|{let(held,saved)=build_retained(c,&input,keep);assert_eq!(saved.len(),index);finish_retained(c,&input,&held,saved);});c.pop_condition();assert_eq!(c.active_qubits(),14);assert_eq!(peak,14+RETENTION_PEAKS[index]);c.declare_qubit_register(&input);let ops=c.take_ops();let(nq,nb,_,_)=analyze_ops(ops.iter());assert_eq!(ops.iter().filter(|o|o.kind==K::CCX).count(),draws);assert_eq!(ops.iter().filter(|o|o.kind==K::Hmr).count(),draws);
   for condition in[0,0xa55a_dd33_ff00_1701,u64::MAX]{for batch in 0..256{for mode in 0..4+draws{let mut bytes=vec![0;draws*8];match mode{0=>{},1=>bytes.fill(255),2=>bytes.fill(0xa5),3=>{let mut h=Shake256::default();h.update(b"retained-prefix-all-coefficients-v1");h.update(&(batch as u64).to_le_bytes());h.finalize_xof().read(&mut bytes);},i=>bytes[(i-4)*8..(i-3)*8].fill(255)}let mut rng=Words{bytes,at:0};let mut s=Simulator::new(nq as usize,nb as usize,&mut rng);for lane in 0..64{let value=batch*64+lane;for(i,&q)in input.iter().enumerate(){s.qubits[q.0 as usize]|=((value>>i&1)as u64)<<lane;}}let initial=s.qubits.clone();s.bits[guard.0 as usize]=condition;s.apply_iter(ops.iter());assert_eq!(s.phase,0,"keep{keep} batch{batch} mode{mode} guard{condition}");for(i,&q)in input.iter().enumerate(){assert_eq!(s.qubits[q.0 as usize],(expected[i][batch]&condition)|(initial[q.0 as usize]&!condition));}for q in 14..nq as usize{assert_eq!(s.qubits[q],0);}assert_eq!(s.stats.toffoli_gates,draws as u64*u64::from(condition.count_ones()));drop(s);assert_eq!(rng.at,draws*8);}}}eprintln!("RETAINED_CORE keep={keep} count={index} ANDs={draws} HMRs={draws} peak_helpers={}",RETENTION_PEAKS[index]);
  }
 }
}
#[cfg(test)]mod prefix_retained_full_fold_tests{
 use super::*;use crate::circuit::{analyze_ops,Op,BitId,OperationType as K};use crate::sim::Simulator;use sha3::{Shake256,digest::{Update,ExtendableOutput,XofReader}};
 struct Words{bytes:Vec<u8>,at:usize}impl XofReader for Words{fn read(&mut self,out:&mut[u8]){out.copy_from_slice(&self.bytes[self.at..self.at+out.len()]);self.at+=out.len();}}
 fn circuit(room:usize,new:bool)->(Vec<Op>,Vec<QubitId>,BitId,u32){let mut c=Builder::new();let acc=c.alloc_qubits(56);let e=c.alloc_qubits(3);let nm=c.alloc_qubits(3);let k1=c.alloc_qubit();let k2=c.alloc_qubit();let guard=c.alloc_bit();let padding=c.alloc_qubits(1233-room-64);let input:Vec<_>=acc.iter().chain(&e).chain(&nm).copied().chain([k1,k2]).collect();let all:Vec<_>=input.iter().chain(&padding).copied().collect();c.declare_qubit_register(&all);c.push_condition(guard);let(_,peak)=super::super::super::super::pingpong::with_phase_cap(Some(if new{1233}else{1250}),||c.r3_peak(|c|{if new{full_fold(c,&acc,[e[0],e[1],e[2]],[nm[0],nm[1],nm[2]],k1,k2,1233);}else{fold_fwd_v2(c,&acc,[e[0],e[1],e[2]],[nm[0],nm[1],nm[2]],k1,k2,0,None,false,2);}}));c.pop_condition();assert_eq!(c.active_qubits(),all.len()as u32);assert!(peak<=if new{1233}else{1250});(c.take_ops(),input,guard,peak)}
 #[test]fn every_retention_frontier_matches_full_fold_with_independent_upper_words(){
  std::env::set_var("PEBBLE_HARD_CAP","1234");for(index,&keep)in RETENTION_MASKS.iter().enumerate(){std::env::set_var("RESEARCH_RETENTION_MASK",keep.to_string());for room in[28+index,30+index]{let old=circuit(room,false);let new=circuit(room,true);assert_eq!(old.1,new.1);let(nq,nb,_,_)=analyze_ops(old.0.iter().chain(&new.0));let mut counts=[0u64;2];
   for condition in[0,0xa55a_dd33_ff00_1701,u64::MAX]{for batch in 0..256{let mut initial=vec![0;nq as usize];let mut h=Shake256::default();h.update(b"retained-prefix-upper-words-v1");h.update(&(batch as u64).to_le_bytes());let mut reader=h.finalize_xof();for &q in &old.1[6..56]{let mut word=[0;8];reader.read(&mut word);initial[q.0 as usize]=u64::from_le_bytes(word);}let core:Vec<_>=old.1[..6].iter().chain(&old.1[56..]).copied().collect();for lane in 0..64{let value=batch*64+lane;for(i,&q)in core.iter().enumerate(){initial[q.0 as usize]|=((value>>i&1)as u64)<<lane;}}for mode in 0..3{let mut results=vec![];for(which,item)in[&old,&new].into_iter().enumerate(){let draws=item.0.iter().filter(|o|matches!(o.kind,K::Hmr|K::R)).count();let mut bytes=vec![0;draws*8];if mode==1{bytes.fill(255);}else if mode==2{let mut h=Shake256::default();h.update(b"retained-prefix-fold-measurements-v1");h.update(&(batch as u64).to_le_bytes());h.finalize_xof().read(&mut bytes);}let mut rng=Words{bytes,at:0};let mut s=Simulator::new(nq as usize,nb as usize,&mut rng);s.qubits.clone_from(&initial);s.bits[item.2.0 as usize]=condition;s.apply_iter(item.0.iter());assert_eq!(s.phase,0,"keep{keep} room{room} new{which} batch{batch}");for q in 0..nq as usize{if !item.1[..56].iter().any(|w|w.0 as usize==q){assert_eq!(s.qubits[q],initial[q]);}}counts[which]+=s.stats.toffoli_gates;results.push(s.qubits.clone());drop(s);assert_eq!(rng.at,draws*8);}assert_eq!(results[0],results[1],"keep{keep} room{room} batch{batch}");}}}eprintln!("RETAINED_FULL_FOLD keep={keep} count={index} room={room} old_peak={} new_peak={} old_executed={} new_executed={} diagnostic_only=1",old.3,new.3,counts[0],counts[1]);
  }}std::env::remove_var("RESEARCH_RETENTION_MASK");
 }
}
